    [InlineData("A99912345/$$52001510X3", "31311111611124215111423131111|32211112522311216221123221111|41211112133331211142514121111|42111131123223411421224211111|33111111421116521132123311111|24111131111136311211352411111|23211121113216115113322321111|23121113432121511431112312111|32121114232212142322123212111|41121111611124413232114112111|41112111422421231162114111211|41111222413113141422214111121|32111211116232421122233211121|31211222211144416111213121121")]
    [InlineData("H123ABC01234567890", "31311111611124215111423131111|32211131621211116133113221111|41211111123234142132224121111|42111141113232533121114211111|33111151114122111315413311111|24111132112143121224232411111|23211111211263433131112321111|23121123521211235212112312111|32121114232212142322123212111|41121111611124312242214112111|41112111432321242211414111211|41111214232113113333124111121|32111232213114411133313211121|31211212613112211221623121121")]
    [InlineData("A1B2C3 D4-E5.F6%G7", "31311111611124215111423131111|32211112522311116133113221111|41211115122321142133214121111|42111144222111433131114211111|33111115311123111422513311111|24111111152223142141312411111|23211134223111231242212321111|23121111211533121222522312111|32121133311213333113123212111|41121144222111531113214112111|41112121231242133312224111211|41111222322411223221144111121|32111234213211134211413211121|31211211414141133221323121121")]
