    [Theory]
    [InlineData("A123BJC5D6E71", "223111142322121513121314112114213222151223212231111|313111211161414513111114121161211321342231113131111|322111134321213162111214211112523121316212113221111|412111111224243212214213311114232212142322124121111|421111116111241161112413221121214214212244114211111|331111113212252111621313131121441122211221623311111|241111142231221233321212231121214241123231142411111|232111221151324121251112321131112612313141132321111")]
