    public void HibcMicroPdf417_FourColumnsMatchReferenceRows(string text, string expected)
        => AssertRows(expected, Encode(new HibcMicroPdf417Symbology(4, false), text));

    /// <summary>
    /// A row is the left row address pattern, the symbol characters, the right row address pattern and a
    /// single module bar, with a centre row address pattern in a symbol of three or four columns: 38, 55,
    /// 82 and 99 modules for one to four columns. The quiet zone is one module on all four sides and the
    /// row height two modules.
    /// </summary>
    /// <param name="columns">The number of data columns.</param>
    /// <param name="width">The row width in modules.</param>
    [Theory]
    [InlineData(1, 38)]
    [InlineData(2, 55)]
    [InlineData(3, 82)]
    [InlineData(4, 99)]
    public void MicroPdf417_RowWidthFollowsTheColumns(int columns, int width)
    {
        StackedBarcodeSymbol symbol = Encode(new MicroPdf417Symbology(columns), "MicroPDF417");

        Assert.All(symbol.Rows, row => Assert.Equal(width, row.WidthInModules));
        Assert.All(symbol.Rows, row => Assert.Equal(1, row.RunWidths[^1]));
        Assert.All(symbol.Rows, row => Assert.All(row.BarHeights, height => Assert.Equal(2F, height)));
        Assert.Equal(1F, symbol.LeadingQuietZone);
        Assert.Equal(1F, symbol.TrailingQuietZone);
        Assert.Equal(1F, symbol.TopQuietZone);
        Assert.Equal(1F, symbol.BottomQuietZone);
    }

    /// <summary>
    /// The largest symbol, four columns of 44 rows with 50 error correction codewords, holds 126 data
    /// codewords, and one column of 28 rows holds 20.
    /// </summary>
    [Fact]
    public void MicroPdf417_RejectsDataThatNoSizeHolds()
    {
        Assert.Throws<ArgumentException>(() => Encode(new MicroPdf417Symbology(), new string('\u00E9', 160)));
        Assert.Throws<ArgumentException>(() => Encode(new MicroPdf417Symbology(1), new string('A', 60)));
    }

    [Fact]
    public void MicroPdf417_RejectsCharactersAboveTheByteRange()
        => Assert.Throws<ArgumentException>(() => Encode(new MicroPdf417Symbology(), "Micro\u0100"));

    [Fact]
    public void MicroPdf417_RejectsColumnsOutsideTheirRange()
    {
        Assert.Throws<ArgumentOutOfRangeException>(() => new MicroPdf417Symbology(0));
        Assert.Throws<ArgumentOutOfRangeException>(() => new MicroPdf417Symbology(5));
    }

    private static StackedBarcodeSymbol Encode(BarcodeSymbology symbology, string text)
        => (StackedBarcodeSymbol)symbology.Encode(text, new BarcodeOptions());

    private static void AssertRows(string expected, StackedBarcodeSymbol symbol)
    {
        string[] rows = expected.Split('|');
        Assert.Equal(rows.Length, symbol.Rows.Length);
        for (int i = 0; i < rows.Length; i++)
        {
            Assert.Equal(rows[i], string.Concat(symbol.Rows[i].RunWidths));
        }
    }
